import{_ as t,o as e,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Why We Have 17 Clusters Instead of One (and Why You Probably Shouldn’t Do Th... O. Kukla & P. Tlapa","description":"","frontmatter":{"title":"Why We Have 17 Clusters Instead of One (and Why You Probably Shouldn’t Do Th... O. Kukla & P. Tlapa","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Distributed Storage","Scalability","High Availability","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Why_We_Have_17_Clusters_Instead_of_One_and_Why_You_Probably_Shouldn_t_Do_Th..._O._Kukla_P._Tlapa.md","filePath":"posts/2025/Why_We_Have_17_Clusters_Instead_of_One_and_Why_You_Probably_Shouldn_t_Do_Th..._O._Kukla_P._Tlapa.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Why_We_Have_17_Clusters_Instead_of_One_and_Why_You_Probably_Shouldn_t_Do_Th..._O._Kukla_P._Tlapa.md"};function _(n,a,s,i,h,u){return e(),l("div",null,[...a[0]||(a[0]=[o('<h3 id="ceph分布式存储解决方案会议纪要" tabindex="-1">Ceph分布式存储解决方案会议纪要 <a class="header-anchor" href="#ceph分布式存储解决方案会议纪要" aria-label="Permalink to &quot;Ceph分布式存储解决方案会议纪要&quot;">​</a></h3><h4 id="_1-会议基本信息" tabindex="-1">1. 会议基本信息 <a class="header-anchor" href="#_1-会议基本信息" aria-label="Permalink to &quot;1. 会议基本信息&quot;">​</a></h4><ul><li><strong>演讲人</strong>：Peter和Andre（CDN77存储团队）</li><li><strong>主题</strong>：大规模Ceph集群的设计、实现与挑战</li><li><strong>背景</strong>：CDN77为全球约10亿用户提供内容分发服务，存储需求庞大且复杂。</li></ul><h4 id="_2-核心问题与需求" tabindex="-1">2. 核心问题与需求 <a class="header-anchor" href="#_2-核心问题与需求" aria-label="Permalink to &quot;2. 核心问题与需求&quot;">​</a></h4><ul><li><strong>数据规模</strong>：约20PB混合数据，对象数量达数百亿且持续增长。</li><li><strong>技术挑战</strong>：高性能读取、高可用性、扩展性、数据分布性。</li><li><strong>需求</strong>：作为CDN源站存储，需支持高吞吐读取，单OSD故障不影响整体集群，未来发展需支持2-3个数量级的增长，数据映射到S3桶。</li></ul><h4 id="_3-解决方案设计" tabindex="-1">3. 解决方案设计 <a class="header-anchor" href="#_3-解决方案设计" aria-label="Permalink to &quot;3. 解决方案设计&quot;">​</a></h4><ul><li><strong>架构概述</strong>：17个独立Ceph集群（14个HDD集群 + 3个SSD集群），双数据中心部署，避免单点故障。</li><li><strong>负载均衡</strong>：基于Nginx的定制一致性哈希模块（chash）分发请求，使用客户端对象的CRC32哈希前4字符作为桶名，确保均匀分布。</li><li><strong>硬件配置</strong>：单节点配置包括24核EPYC CPU、512GB RAM、30×24TB HDD + 6×NVMe。</li></ul><h4 id="_4-实施中的挑战与经验" tabindex="-1">4. 实施中的挑战与经验 <a class="header-anchor" href="#_4-实施中的挑战与经验" aria-label="Permalink to &quot;4. 实施中的挑战与经验&quot;">​</a></h4><ul><li><strong>管理复杂度</strong>：多集群操作、Bucket列表操作困难。</li><li><strong>扩展性问题</strong>：新增集群需手动迁移数据。</li><li><strong>生产环境问题</strong>：Bucket命名长度初始设置错误，版本统计差异，Lifecycle策略导致性能峰值。</li></ul><h4 id="_5-关键结论与未来计划" tabindex="-1">5. 关键结论与未来计划 <a class="header-anchor" href="#_5-关键结论与未来计划" aria-label="Permalink to &quot;5. 关键结论与未来计划&quot;">​</a></h4><ul><li><strong>方案评估</strong>：满足高性能、可扩展S3端点的需求，但管理开销大，扩展需谨慎。</li><li><strong>改进方向</strong>：探索自动化工具、研究更高效的EC方案。</li></ul><h4 id="_6-q-a环节摘要" tabindex="-1">6. Q&amp;A环节摘要 <a class="header-anchor" href="#_6-q-a环节摘要" aria-label="Permalink to &quot;6. Q&amp;A环节摘要&quot;">​</a></h4><ul><li><strong>灾备恢复</strong>：依赖双数据中心设计，故障时切换至备用集群，数据从对端DC同步。</li><li><strong>扩展建议</strong>：优先扩容现有集群。</li></ul><h4 id="_7-后续行动" tabindex="-1">7. 后续行动 <a class="header-anchor" href="#_7-后续行动" aria-label="Permalink to &quot;7. 后续行动&quot;">​</a></h4><ul><li><strong>短期</strong>：优化监控指标。</li><li><strong>长期</strong>：评估Ceph Multicite以简化多集群管理。</li></ul><p><strong>备注</strong>：如需进一步技术细节，请联系演讲团队。</p><p><strong>关键词保留</strong>：Ceph, CRUSH, RADOS, RGW, OSD, RocksDB, EC (Erasure Coding), replication, bucket, S3 endpoint.</p>',17)])])}const c=t(r,[["render",_]]);export{g as __pageData,c as default};
